1	package templates
2	
3	import (
4		"strconv"
5		"strings"
6	
7		"github.com/charmbracelet/lipgloss"
8	
9		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
10		"github.com/anthnel/devdesk/internal/ui/help"
11		"github.com/anthnel/devdesk/internal/ui/keymap"
12		"github.com/anthnel/devdesk/internal/ui/shortcut"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// GetTitle names the view, and the form when one is open.
17	func (m Model) GetTitle() string {
18		base := theme.IconRepository + " Templates"
19		if m.selecting {
20			return base + " " + theme.IconChevronRight + " Choose a template"
21		}
22		if m.form != nil {
23			return base + " " + theme.IconChevronRight + " " + m.form.GetTitle()
24		}
25		return base
26	}
27	
28	// GetIcon returns the view icon. The title carries it, as everywhere else.
29	func (m Model) GetIcon() string { return "" }
30	
31	// GetHeaderInfo says how many templates are on screen. The count is what says
32	// why the table is empty — no template, or a filter matching none — since the
33	// body is always the table (Rule 139).
34	func (m Model) GetHeaderInfo(_ string) []shortcut.HeaderInfo {
35		return []shortcut.HeaderInfo{
36			{Key: "Templates", Value: strconv.Itoa(len(m.table.Visible())), Style: theme.HeaderValueStyle},
37		}
38	}
39	
40	// GetShortcuts returns the header's shortcut column (Rules 130, 137, 138).
41	//
42	// A mode replaces the list; a state inside the list only greys entries.
43	func (m Model) GetShortcuts() shortcut.Shortcuts {
44		if m.confirmModal != nil {
45			return []shortcut.Shortcut{
46				{Key: "←→", Description: "Choose"},
47				{Key: "enter", Description: "Confirm"},
48				{Key: "esc", Description: "Cancel"},
49			}
50		}
51		if m.form != nil {
52			return []shortcut.Shortcut{
53				// Structural: ←→ only means something on the source field, and there
54				// is nothing to explain about a lost arrow key (Rule 130).
55				{Key: "←→", Description: "Change source", Disabled: !m.form.OnCycleField()},
56				{Key: "enter", Description: m.form.EnterDescription()},
57				{Key: "esc", Description: "Cancel"},
58			}
59		}
60	
61		a := m.availability()
62		if m.selecting {
63			return []shortcut.Shortcut{
64				{Key: "enter", Description: "Choose template", Disabled: !a.Preview.Enabled()},
65				{Key: keymap.Pager, Description: "Preview files", Disabled: !a.Preview.Enabled()},
66				{Key: ".", Description: "Sort"},
67				{Key: "/", Description: "Filter"},
68				{Key: "esc", Description: "Cancel"},
69				{Key: "?", Description: "Help"},
70			}
71		}
72		return []shortcut.Shortcut{
73			{Key: keymap.New, Description: "Create template", Disabled: !a.New.Enabled()},
74			{Key: keymap.Edit, Description: "Edit template", Disabled: !a.Edit.Enabled()},
75			{Key: keymap.Delete, Description: "Delete template", Disabled: !a.Delete.Enabled()},
76			{Key: keymap.Scan, Description: "Scan template", Disabled: !a.Scan.Enabled()},
77			{Key: keymap.Fetch, Description: "Sync template", Disabled: !a.Sync.Enabled()},
78			{Key: keymap.Pager, Description: "Preview files", Disabled: !a.Preview.Enabled()},
79			{Key: ".", Description: "Sort"},
80			{Key: "/", Description: "Filter"},
81			{Key: "?", Description: "Help"},
82		}
83	}
84	
85	// InEditMode tells the router a field or the filter has the keyboard: `:` is a
86	// character in a URL (app.FormView).
87	func (m Model) InEditMode() bool {
88		return m.form != nil || m.confirmModal != nil || m.table.InEditMode()
89	}
90	
91	// FilterBarVisible closes the viewport rectangle around the bar
92	// (app.FilterBarView). It is not shown under a form or a modal.
93	func (m Model) FilterBarVisible() bool {
94		return m.form == nil && m.confirmModal == nil && m.table.FilterBar().IsVisible()
95	}
96	
97	// GetFooterHeight budgets the footer (Rules 124, 136).
98	func (m Model) GetFooterHeight() int {
99		if m.form != nil || m.confirmModal != nil {
100			return 2
101		}
102		return 2 + m.table.FilterBar().ExtraHeight()
103	}
104	
105	// RenderFooter renders the lines below the viewport: filter bar, blank, message.
106	func (m Model) RenderFooter(width int) string {
107		var parts []string
108		if m.FilterBarVisible() {
109			parts = append(parts, m.table.FilterBar().View())
110		}
111		parts = append(parts, theme.EmptyLineBg(width), m.footer.View(width, m.status()))
112		return strings.Join(parts, "\n")
113	}
114	
115	// status is the derived line, with no timer (Rule 128): the prompt while the
116	// view is lent, the live work otherwise. Both are states, not events.
117	func (m Model) status() sharedcomponents.Status {
118		if m.selecting {
119			return sharedcomponents.Status{Text: m.selectionMessage}
120		}
121		return m.jobsStatus()
122	}
123	
124	// View renders the form, the modal, or the table — and the table whatever it
125	// holds: while loading, empty, or filtered to nothing it is a header and no rows
126	// (Rule 139).
127	func (m Model) View() string {
128		if m.form != nil {
129			return m.form.View()
130		}
131		if m.confirmModal != nil {
132			return lipgloss.Place(
133				m.width, m.height,
134				lipgloss.Center, lipgloss.Center,
135				m.confirmModal.View(),
136				lipgloss.WithWhitespaceBackground(theme.ColorBackground),
137			)
138		}
139		return m.table.View()
140	}
141	
142	// GetHelpContent returns the help for `?` (Rule 114).
143	func (m Model) GetHelpContent() help.Content {
144		bindings := []help.KeyBinding{
145			{Key: keymap.New, Description: "Add a template to the catalog"},
146			{Key: keymap.Edit, Description: "Edit the selected template"},
147			{Key: keymap.Delete, Description: "Remove the selected template from the catalog. The template's own content is never touched"},
148			{Key: keymap.Fetch, Description: "Sync the selected template: read its source again and replace the cached copy"},
149			{Key: keymap.Pager, Description: "Preview the files the template would put in a new repository"},
150			{Key: ".", Description: "Cycle the sort column. Each press toggles asc/desc, then moves to the next column"},
151			{Key: "/", Description: "Filter by name, description, tags or source"},
152			{Key: "ctrl+p", Description: "Open command mode"},
153			{Key: "?", Description: "Show this help"},
154		}
155		if m.selecting {
156			bindings = []help.KeyBinding{
157				{Key: "enter", Description: "Use the selected template for the new repository"},
158				{Key: keymap.Pager, Description: "Preview the files the template would put in the repository"},
159				{Key: ".", Description: "Cycle the sort column"},
160				{Key: "/", Description: "Filter by name, description, tags or source"},
161				{Key: "esc", Description: "Go back to the form without choosing: the template stays as it was"},
162				{Key: "?", Description: "Show this help"},
163			}
164		}
165		return help.Content{
166			Title: "Templates",
167			Description: "The catalog of repository templates. A template is a reference to content that lives somewhere else — " +
168				"a git repository, a directory on this machine, or an artifact in an OCI registry — and it is fetched from there when it is needed, " +
169				"so the catalog cannot drift from the original.",
170			KeyBindings: bindings,
171			Sections: []help.Section{
172				{
173					Title: "Sources",
174					Body: "git: a remote repository. Give the clone URL, optionally a subdirectory to use as the template's root, and a branch, tag or commit.\n" +
175						"local: a git repository on this machine. Only what is committed is used — no .git, nothing ignored, no uncommitted edit — so a template never depends on the state of a working tree. Enter on the directory (" + theme.IconBrowse + ") opens the file browser to choose it, and ~ stands for your home.\n" +
176						"oci: an artifact in a registry — the registry URL, the repository and the tag.\n\n" +
177						"A URL may be https, ssh, git or the scp form (git@host:path). Nothing else is accepted: the catalog file can be shared, and a URL is not trusted.",
178				},
179				{
180					Title: "Tags",
181					Body:  "Free-form labels — java, spring-boot, ci-component — separated by commas. They are lowercased and de-duplicated, and searched by the filter as stored.",
182				},
183				{
184					Title: "The catalog",
185					Body: "Templates are kept in ~/.devdesk/templates.yaml and shared by every context. " +
186						"When a repository is created, the Template field of the form offers this list, or none for an empty repository.",
187				},
188				{
189					Title: "Scanning",
190					Body: "'" + keymap.Scan + "' fetches the template, writes it to ~/.devdesk/cache/template-scan/<name> and scans that directory with the configured scanners, the way a repository is scanned. " +
191						"The result is kept by path, so it appears in :sec, which is where the report opens; the footer here gives the counts. " +
192						"A scan replaces the previous copy, so what is scanned is what the template holds now. The CI score is not computed: a template has no pipeline to grade.\n" +
193						"The key is greyed when neither Trivy nor Gitleaks is available, and while a scan of that template is already running.",
194				},
195				{
196					Title: "Syncing",
197					Body: "A template's files are read once and kept in ~/.devdesk/cache/templates/<name>.json; a preview, a scan and a new repository all start from that copy. " +
198						"It is not refreshed on its own, so a branch that moved on, or a local repository that gained a commit, is served as it was until '" + keymap.Fetch + "' reads the source again. " +
199						"The Synced column says how old the copy is. A template pinned to a commit needs no sync. A failed sync keeps the previous copy, and a copy made for a source that has since been edited is not used.\n" +
200						"The key is greyed while a sync of that template is already running.",
201				},
202				{
203					Title: "Credentials",
204					Body: "A source is fetched anonymously unless it is on the same host as the context's forge (git) or registry (oci), in which case the stored token or password is used. " +
205						"A token authenticates one host, so it is never offered to another: a private repository on any other host needs an SSH URL.",
206				},
