// NewRun builds a run with every target queued. StartedAt is left to the
// registry, which stamps it when the run is admitted.
func NewRun(kind Kind, origin command.ViewType, contextName, label string, targets ...string) Run {
	items := make([]Item, len(targets))
	for i, target := range targets {
		items[i] = Item{Target: target, State: ItemQueued}
	}
	return Run{
		Kind:    kind,
		Origin:  origin,
		Context: contextName,
		Label:   label,
		Items:   items,
	}
}

// NewImmediateRun builds a single-target run whose item is already running.
//
// It is for work that goes out with its start message (a create, a delete):
// nothing queues in front of it, so showing the item as queued would be a lie
// for as long as the first transition takes to arrive.
func NewImmediateRun(kind Kind, origin command.ViewType, contextName, label, target string) Run {
	run := NewRun(kind, origin, contextName, label, target)
	run.Items[0].State = ItemRunning
	return run
}

// NewOpenRun builds a run whose targets are not known yet.
//
// It is the clone's shape and only the clone's: the walk that discovers
// repositories is itself the slow part, so a run that waited for the full list
// would show nothing for the minutes that matter. Targets arrive through
// Registry.Discover, and Registry.Seal says there will be no more.
func NewOpenRun(kind Kind, origin command.ViewType, contextName, label string) Run {
	return Run{
		Kind:    kind,
		Origin:  origin,
		Context: contextName,
		Label:   label,
		open:    true,
	}
}

// Open reports whether the run is still discovering its targets.
func (r Run) Open() bool { return r.open }

// WithDisplay names how one target should be printed. It is separate from
// NewRun because only some kinds have one — an image reference goes through a
// registry alias, a repository path does not.
func (r Run) WithDisplay(target, display string) Run {
	items := make([]Item, len(r.Items))
	copy(items, r.Items)
	for i := range items {
		if items[i].Target == target {
			items[i].Display = display
		}
	if r.clock == nil {
		return time.Now()
	}
	return r.clock()
}

// Failures returns a copy of the remembered failures, oldest first. Like the
// rest of the registry it is read from Update alone (Rule 110).
func (r *Registry) Failures() []Failure {
	return slices.Clone(r.failures)
}

// Forget drops every failure of every kind on target in contextName, and those
// below it when target is an absolute path. It reports whether anything went.
func (r *Registry) Forget(target, contextName string) bool {
	target = TargetKey(target)
	before := len(r.failures)
	r.failures = slices.DeleteFunc(r.failures, func(f Failure) bool {
		return f.Context == contextName && (f.Target == target || isBelow(f.Target, target))
	})
	return len(r.failures) != before
}

// record is the single rule of the failure memory, called after an item's
// state is written: failed poses, done clears (and a successful delete forgets
// the target for every kind). Any other state, including skipped, changes
// nothing. The context is the run's, so a failure landing after a context
// switch is filed under the context it ran in.
func (r *Registry) record(run *Run, item Item) {
	switch item.State {
	case ItemFailed:
		if run.Kind.Remembered() {
			r.pose(Failure{
				FailureKey: failureKey(run.Kind, item.Target, run.Context),
				Display:    item.Name(),
				Detail:     item.Detail,
				At:         r.now(),
			})
		}
	case ItemDone:
		r.clear(failureKey(run.Kind, item.Target, run.Context))
		if run.Kind == KindDelete {
			r.Forget(item.Target, run.Context)
		}
	}
}

// pose stores f as the last failure for its key. Re-posing a key moves it to
// the newest position; past MaxFailures the oldest entry is evicted.
func (r *Registry) pose(f Failure) {
	r.clear(f.FailureKey)
	r.failures = append(r.failures, f)
	if excess := len(r.failures) - MaxFailures; excess > 0 {
		r.failures = slices.Delete(r.failures, 0, excess)
	}
}

// clear drops the failure stored under key, if any.
func (r *Registry) clear(key FailureKey) {
	r.failures = slices.DeleteFunc(r.failures, func(f Failure) bool { return f.FailureKey == key })
}

func failureKey(kind Kind, target, contextName string) FailureKey {
	return FailureKey{Kind: kind, Target: TargetKey(target), Context: contextName}
}

// isBelow reports whether path is strictly inside dir. Only absolute paths
// have descendants: image references and forge paths are matched exactly.
func isBelow(path, dir string) bool {
	if !filepath.IsAbs(path) || !filepath.IsAbs(dir) {
		return false
	}
	rel, err := filepath.Rel(dir, path)
	return err == nil && rel != "." && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
}
