51	// pendingTable is a table that still has to move to the activity column.
52	type pendingTable struct {
53		Table string
54		View  command.ViewType
55		Story string
56	}
57	
58	// pendingTables may only shrink: each migration story removes its own entries.
59	var pendingTables = []pendingTable{
60		{"oci/registry-browser", command.ViewOCIResources, "A-09a2"},
61		{"oci/networks", command.ViewOCIResources, "A-09b"},
62		{"oci/volumes", command.ViewOCIResources, "A-09b"},
