152	// staleExceptions lists the pending tables of a view that the view already
153	// reports: their exception must go.
154	func staleExceptions(vt command.ViewType, reported []string, pending []pendingTable) []string {
155		var stale []string
156		for _, p := range pending {
157			if p.View == vt && contains(reported, p.Table) {
158				stale = append(stale, p.Table)
159			}
160		}
161		return stale
162	}
