340	// sourceDeclarationProblems says what is wrong with the link between migrated
341	// views and the sources scanned for them, empty when it is fine. files are the
342	// paths relative to internal/ of every non-test source file.
343	func sourceDeclarationProblems(migrated map[command.ViewType][]string, sources map[command.ViewType][]string, files []string) []string {
344		var problems []string
345		for vt := range migrated {
346			if len(sources[vt]) == 0 {
347				problems = append(problems, fmt.Sprintf("view %q is migrated but declares no source to scan in migratedSources", vt))
348			}
349		}
350		for vt, prefixes := range sources {
351			if len(migrated[vt]) == 0 {
352				problems = append(problems, fmt.Sprintf("view %q has sources in migratedSources but is not migrated (migratedTables)", vt))
353			}
354			for _, p := range prefixes {
355				if !anyHasPrefix(files, p) {
356					problems = append(problems, fmt.Sprintf("view %q: source prefix %q matches no file", vt, p))
357				}
358			}
359		}
360		sort.Strings(problems)
361		return problems
362	}
363	
364	func anyHasPrefix(files []string, prefix string) bool {
365		for _, f := range files {
366			if prefix != "" && strings.HasPrefix(f, prefix) {
367				return true
368			}
369		}
370		return false
371	}
