418	// declaredViewTicks are the tea.Tick / tea.Every calls a migrated view may
419	// still make, keyed "<file relative to internal/>:<function>" with the reason.
420	// Empty today: the router's one tick animates every row (DEVDESK-139). The list
421	// may only shrink.
422	var declaredViewTicks = map[string]string{}
423	
424	// declaredGlyphConstants are the constants a migrated view may still define with
425	// an activity glyph in them, keyed "<file relative to internal/>:<constant>" with
426	// the reason (DEVDESK-144, decision Q4-A). The exception is the constant, not the
427	// file: any other literal in the same file is still rejected, so the help text
428	// has to build its sentence from the constant. The list may only shrink.
429	var declaredGlyphConstants = map[string]string{
430		"ui/workspaces/view.go:gitMarkNoUpstream": "git marker for a branch with no upstream; it is a git fact, not a row state, and ws never shows the cancelled state, so nothing on screen is ambiguous (changing the marker is a UX ticket of its own)",
431	}
432	
433	// finding is one retired mechanism found in a source file.
434	type finding struct {
435		Pos  token.Position // file:line:column
436		What string
437	}
438	
439	// bubbleTeaName returns the local name file gives the bubbletea import: its
440	// alias, "." for a dot import, "tea" when unnamed, or "" when the file does not
441	// import it (or blank-imports it). A different package that happens to be
442	// called tea is therefore not mistaken for it.
443	func bubbleTeaName(file *ast.File) string {
444		for _, imp := range file.Imports {
445			path, err := strconv.Unquote(imp.Path.Value)
446			if err != nil || path != "github.com/charmbracelet/bubbletea" {
447				continue
448			}
449			switch {
450			case imp.Name == nil:
451				return "tea"
452			case imp.Name.Name == "_":
453				return ""
454			default:
455				return imp.Name.Name
456			}
457		}
458		return ""
459	}
460	
461	// retiredMechanisms reports, in a migrated view's file, every retired
462	// mechanism: AdvanceSpinner, a StatusColumn: key, a frame field, an activity
463	// glyph literal, and any reference to bubbletea's Tick / Every (under whatever name the file
464	// imports it) outside declaredViewTicks.
465	// rel is the file's path relative to internal/; it is the key of a declared tick.
466	// RenderedFrame (a method of the viewport frame) is allowed.
467	func retiredMechanisms(fset *token.FileSet, file *ast.File, rel string) []finding {
468		var out []finding
469		report := func(pos token.Pos, what string) {
470			out = append(out, finding{Pos: fset.Position(pos), What: what})
471		}
472		tea := bubbleTeaName(file)
473		selectors := map[*ast.Ident]bool{} // identifiers seen as the Sel of a selector
474		// reportTick flags any reference to bubbletea's Tick / Every, called or not
475		// (`var tick = tea.Tick` is as much a tick as `tea.Tick(...)`), unless the
476		// enclosing "<file>:<function>" is declared.
477		reportTick := func(pos token.Pos, fn, name string) {
478			if name != "Tick" && name != "Every" {
479				return
480			}
481			if _, declared := declaredViewTicks[rel+":"+fn]; !declared {
482				report(pos, "reference to bubbletea's "+name+" (a view's rows are animated by the router's tick)")
483			}
484		}
485		isFrame := func(name string) bool {
486			return name == "Frame" || name == "frame" || name == "SpinnerFrame"
487		}
488		visit := func(fn string) func(ast.Node) bool {
489			return func(n ast.Node) bool {
490				switch x := n.(type) {
491				case *ast.CallExpr:
492					sel, ok := x.Fun.(*ast.SelectorExpr)
493					if !ok {
494						break
495					}
496					if sel.Sel.Name == "AdvanceSpinner" {
497						report(x.Pos(), "call to AdvanceSpinner")
498					}
499				case *ast.KeyValueExpr:
500					if id, ok := x.Key.(*ast.Ident); ok {
501						if id.Name == "StatusColumn" {
502							report(id.Pos(), "StatusColumn: key")
503						}
504						if isFrame(id.Name) {
505							report(id.Pos(), "frame field "+id.Name+": set")
506						}
507					}
508				case *ast.Field:
509					for _, id := range x.Names {
510						if isFrame(id.Name) {
511							report(id.Pos(), "frame field "+id.Name)
512						}
513					}
514				case *ast.Ident:
515					// Dot import: a bare Tick / Every that no declaration in the file binds.
516					if tea == "." && x.Obj == nil && !selectors[x] {
517						reportTick(x.Pos(), fn, x.Name)
518					}
519				case *ast.SelectorExpr:
520					selectors[x.Sel] = true
521					if pkg, ok := x.X.(*ast.Ident); ok && tea != "" && tea != "." && pkg.Name == tea {
522						reportTick(x.Pos(), fn, x.Sel.Name)
523					}
524					if isFrame(x.Sel.Name) {
525						report(x.Sel.Pos(), "frame selector ."+x.Sel.Name)
526					}
527				case *ast.BasicLit:
528					if x.Kind == token.STRING || x.Kind == token.CHAR {
529						s, err := strconv.Unquote(x.Value)
530						if x.Kind == token.CHAR {
531							var q rune
532							q, _, _, err = strconv.UnquoteChar(x.Value[1:len(x.Value)-1], '\'')
533							s = string(q)
534						}
535						if err == nil && strings.ContainsAny(s, activityGlyphs) {
536							report(x.Pos(), "activity glyph written as a literal "+x.Value+" (use indicator.Glyph)")
537						}
538					}
539				}
540				return true
541			}
542		}
543		for _, decl := range file.Decls {
544			fn := ""
545			if fd, ok := decl.(*ast.FuncDecl); ok {
546				fn = fd.Name.Name
547			}
548			if gd, ok := decl.(*ast.GenDecl); ok && gd.Tok == token.CONST {
549				for _, spec := range gd.Specs {
550					if isDeclaredGlyphConstant(rel, spec) {
551						continue
552					}
553					ast.Inspect(spec, visit(fn))
554				}
555				continue
556			}
557			ast.Inspect(decl, visit(fn))
558		}
559		return out
560	}
561	
562	// isDeclaredGlyphConstant reports whether spec defines only constants declared in
563	// declaredGlyphConstants for the file rel.
564	func isDeclaredGlyphConstant(rel string, spec ast.Spec) bool {
565		vs, ok := spec.(*ast.ValueSpec)
566		if !ok || len(vs.Names) == 0 {
567			return false
568		}
569		for _, id := range vs.Names {
570			if _, declared := declaredGlyphConstants[rel+":"+id.Name]; !declared {
571				return false
572			}
573		}
574		return true
575	}
576	
577	// Criterion 2a/2b: no retired mechanism and no tick in a migrated view.
578	func TestActivityGuardMigratedSourcesUseNoRetiredMechanism(t *testing.T) {
579		scanned := 0
580		sourceFiles(t, func(rel string, fset *token.FileSet, file *ast.File) {
581			if !hasAnyPrefix(rel, allMigratedSources()) {
582				return
583			}
584			scanned++
585			for _, f := range retiredMechanisms(fset, file, rel) {
586				t.Errorf("%s: %s in a migrated view (A-16 criterion 2/3)", f.Pos, f.What)
587			}
588		})
589		if scanned == 0 {
590			t.Fatalf("no source file found under %v: the scan reads nothing", migratedSources)
591		}
592		for key, reason := range declaredViewTicks {
593			if reason == "" {
594				t.Errorf("declared view tick %q names no reason", key)
595			}
596		}
597		for key, reason := range declaredGlyphConstants {
598			if reason == "" {
599				t.Errorf("declared glyph constant %q names no reason", key)
600			}
601		}
602	}
603	
604	// A declared glyph constant must still exist and still hold a glyph, otherwise
605	// the exception is stale and must go; and it excuses that constant only.
606	func TestActivityGuardDeclaredGlyphConstantsAreLive(t *testing.T) {
607		live := map[string]bool{}
608		sourceFiles(t, func(rel string, fset *token.FileSet, file *ast.File) {
609			for _, decl := range file.Decls {
610				gd, ok := decl.(*ast.GenDecl)
611				if !ok || gd.Tok != token.CONST {
612					continue
613				}
614				for _, spec := range gd.Specs {
615					vs, ok := spec.(*ast.ValueSpec)
616					if !ok {
617						continue
618					}
619					for i, id := range vs.Names {
620						key := rel + ":" + id.Name
621						if _, declared := declaredGlyphConstants[key]; !declared || i >= len(vs.Values) {
622							continue
623						}
624						if lit, ok := vs.Values[i].(*ast.BasicLit); ok {
625							s, _ := strconv.Unquote(lit.Value)
626							live[key] = strings.ContainsAny(s, activityGlyphs)
627						}
628					}
629				}
630			}
631		})
632		for key := range declaredGlyphConstants {
633			if !live[key] {
634				t.Errorf("declared glyph constant %q does not exist or holds no activity glyph: remove the exception", key)
635			}
636		}
637		if got := len(declaredGlyphConstants); got > 1 {
638			t.Errorf("declaredGlyphConstants has %d entries, ceiling is 1: the list may only shrink", got)
639		}
640	}
641	
642	// The exception covers the constant and nothing else in the file.
643	func TestActivityGuardGlyphConstantExceptionIsNarrow(t *testing.T) {
644		src := "package v\nconst gitMarkNoUpstream = \"\u2298\"\nconst other = \"\u2298\"\nvar help = \"a \u2298 b\"\n"
645		fset := token.NewFileSet()
646		file, err := parser.ParseFile(fset, "view.go", src, 0)
647		if err != nil {
648			t.Fatal(err)
649		}
650		got := retiredMechanisms(fset, file, "ui/workspaces/view.go")
651		if len(got) != 2 {
652			t.Fatalf("findings = %v, want the undeclared const and the var literal only", got)
653		}
654		for _, f := range got {
655			if f.Pos.Line == 2 {
656				t.Errorf("the declared constant was flagged: %v", f)
657			}
658		}
659	}
660	
661	// The detection itself, on sources held in strings.
662	func TestActivityGuardRetiredMechanismsLogic(t *testing.T) {
663		const head = "package v\nimport tea \"github.com/charmbracelet/bubbletea\"\nimport \"github.com/charmbracelet/bubbles/spinner\"\n"
664		const (
665			bt    = "package v\nimport bt \"github.com/charmbracelet/bubbletea\"\nimport \"github.com/charmbracelet/bubbles/spinner\"\n"
666			dot   = "package v\nimport . \"github.com/charmbracelet/bubbletea\"\nimport \"github.com/charmbracelet/bubbles/spinner\"\n"
667			other = "package v\nimport tea \"example.com/notbubbletea\"\nimport \"github.com/charmbracelet/bubbles/spinner\"\n"
668		)
669		tests := []struct {
670			name     string
671			head     string // import block overriding head; it must keep the same 3 lines
672			body     string
673			declared map[string]string
674			want     int
675			at       string // "line:column" of the first finding, when want > 0
676		}{
677			{"tea.Tick", "", "func f() { _ = tea.Tick(0, nil) }", nil, 1, "4:16"},
678			{"tea.Every", "", "func f() { _ = tea.Every(0, nil) }", nil, 1, "4:16"},
679			{"spinner.Tick is not a view tick", "", "func f() { _ = spinner.Tick }\nfunc g() { _ = spinner.Tick() }", nil, 0, ""},
680			{"declared tick", "", "func f() { _ = tea.Tick(0, nil) }", map[string]string{"ui/v/v.go:f": "why"}, 0, ""},
681			{"tick declared for another function", "", "func g() { _ = tea.Tick(0, nil) }", map[string]string{"ui/v/v.go:f": "why"}, 1, "4:16"},
682			{"AdvanceSpinner", "", "func f(t T) { t.AdvanceSpinner() }", nil, 1, "4:15"},
683			{"glyph literal", "", "var g = \"\u25cf\"", nil, 1, "4:9"},
684			{"clean", "", "func f() {}", nil, 0, ""},
685			{"aliased import", bt, "func f() { _ = bt.Tick(0, nil) }", nil, 1, "4:16"},
686			{"dot import", dot, "func f() { _ = Tick(0, nil) }", nil, 1, "4:16"},
687			{"dot import, bare reference", dot, "var tick = Every", nil, 1, "4:12"},
688			{"package variable holding tea.Tick", "", "var tick = tea.Tick", nil, 1, "4:12"},
689			{"tick in a method", "", "func (m M) f() { _ = tea.Tick(0, nil) }", nil, 1, "4:22"},
690			{"declared tick, aliased import", bt, "func f() { _ = bt.Tick(0, nil) }", map[string]string{"ui/v/v.go:f": "why"}, 0, ""},
691			{"non-bubbletea package named tea", other, "func f() { _ = tea.Tick(0, nil) }", nil, 0, ""},
692			{"dot import does not flag a method named Tick", dot, "func f(t T) { t.Tick() }", nil, 0, ""},
693		}
694		for _, tt := range tests {
695			t.Run(tt.name, func(t *testing.T) {
696				old := declaredViewTicks
697				declaredViewTicks = tt.declared
698				defer func() { declaredViewTicks = old }()
699				fset := token.NewFileSet()
700				h := head
701				if tt.head != "" {
702					h = tt.head
703				}
704				src := h + tt.body
705				file, err := parser.ParseFile(fset, "v.go", src, 0)
706				if err != nil {
707					t.Fatal(err)
708				}
709				got := retiredMechanisms(fset, file, "ui/v/v.go")
710				if len(got) != tt.want {
711					t.Fatalf("findings = %v, want %d", got, tt.want)
712				}
713				if tt.want > 0 {
714					if at := fmt.Sprintf("%d:%d", got[0].Pos.Line, got[0].Pos.Column); at != tt.at {
715						t.Errorf("first finding at %s, want %s", at, tt.at)
716					}
717				}
718			})
719		}
720	}
721	
722	func allMigratedSources() []string {
723		var out []string
724		for _, prefixes := range migratedSources {
725			out = append(out, prefixes...)
726		}
727		return out
728	}
729	
730	func hasAnyPrefix(s string, prefixes []string) bool {
731		for _, p := range prefixes {
732			if strings.HasPrefix(s, p) {
733				return true
734			}
735		}
736		return false
737	}
738	
739	func contains(list []string, s string) bool {
740		for _, x := range list {
741			if x == s {
742				return true
743			}
744		}
745		return false
746	}
747	
748	func sortedKeys(m map[string]datatable.ActivityTable) []string {
749		out := make([]string, 0, len(m))
750		for k := range m {
751			out = append(out, k)
752		}
753		sort.Strings(out)
754		return out
755	}
756	
757	// footerRenderer is what a view exposes for its footer (the router's contract,
758	// restated so the guard reads it without the router).
759	type footerRenderer interface {
760		RenderFooter(width int) string
761	}
762	
763	// migratedFooterSeeds put a migrated view on screen with one active row selected
764	// and return the state that row is in. A migrated view without a seed fails the
765	// guard by name.
766	var migratedFooterSeeds = map[command.ViewType]func(*testing.T, *App) indicator.State{
767		command.ViewJobs:         seedJobsFooter,
768		command.ViewWorkspaces:   seedWorkspacesFooter,
769		command.ViewSecurity:     seedSecurityFooter,
770		command.ViewOCIResources: seedOCIFooter,
771		command.ViewGitExplorer:  seedExplorerFooter,
772	}
773	
774	// seedOCIFooter puts a scan of the first Images row (nginx:1.27, the selected
775	// one) in the running state and opens the OCI view on it.
776	func seedOCIFooter(t *testing.T, a *App) indicator.State {
777		t.Helper()
778		t.Setenv("PATH", t.TempDir()) // no docker: a reload command must stay inert
779		const image = "nginx:1.27"
780		a.Update(jobs.StartMsg{Run: jobs.NewRun(jobs.KindScan, command.ViewOCIResources, "", "images", image)})
781		snap := a.jobs.Snapshot()
782		if len(snap) != 1 || !a.jobs.Advance(snap[0].ID, image, jobs.ItemRunning, "") {
783			t.Fatalf("the seed could not put the scan in the running state: %+v", snap)
784		}
785		openOCI(t, a)
786		return indicator.Running
787	}
788	
789	// seedJobsFooter starts a scan run, moves its item to running (a started run
790	// is queued until a transition says otherwise), and opens :jobs, whose first run
791	// is selected.
792	func seedJobsFooter(t *testing.T, a *App) indicator.State {
793		t.Helper()
794		a.Update(jobs.StartMsg{Run: scanRun("default", "a")})
795		snap := a.jobs.Snapshot()
796		if len(snap) != 1 || !a.jobs.Advance(snap[0].ID, "a", jobs.ItemRunning, "") {
797			t.Fatalf("the seed could not put the run's item in the running state: %+v", snap)
798		}
799		testutil.Msgs(a.switchView(command.ViewJobs))
800		a.resize(a.width, a.height)
801		return indicator.Running
802	}
803	
804	// footerSeedProblems says which migrated views have no seed, and which seeds
805	// belong to no migrated view.
806	func footerSeedProblems(migrated map[command.ViewType][]string, seeds map[command.ViewType]func(*testing.T, *App) indicator.State) []string {
807		var problems []string
808		for vt := range migrated {
809			if seeds[vt] == nil {
810				problems = append(problems, fmt.Sprintf("view %q is migrated but has no entry in migratedFooterSeeds", vt))
811			}
812		}
813		for vt := range seeds {
814			if len(migrated[vt]) == 0 {
815				problems = append(problems, fmt.Sprintf("view %q has a footer seed but is not migrated", vt))
816			}
817		}
818		sort.Strings(problems)
819		return problems
820	}
821	
822	// footerGlyphProblem is empty when footer carries the glyph of state. The footer
823	// glyph never blinks, so the steady one (on = true) is the one to look for.
824	func footerGlyphProblem(footer string, state indicator.State) string {
825		glyph := indicator.Glyph(state, true)
826		if glyph == "" {
827			return fmt.Sprintf("state %v has no glyph: the seed must put the row in a visible state", state)
828		}
829		if !strings.Contains(ansi.Strip(footer), glyph) {
830			return fmt.Sprintf("the footer does not carry the glyph %q of state %v", glyph, state)
831		}
832		return ""
833	}
834	
835	// Criterion 5, footer half: the selected row's footer says its state with the
836	// same glyph as the column.
837	func TestActivityGuardMigratedFooterCarriesTheRowGlyph(t *testing.T) {
838		for _, p := range footerSeedProblems(migratedTables, migratedFooterSeeds) {
839			t.Error(p)
840		}
841		for vt, seed := range migratedFooterSeeds {
842			if seed == nil || len(migratedTables[vt]) == 0 {
843				continue
844			}
845			t.Run(string(vt), func(t *testing.T) {
846				a := routerAt(t, &bareView{}, 180, 40)
847				state := seed(t, a)
848				fr, ok := a.views[vt].(footerRenderer)
849				if !ok {
850					t.Fatalf("view %q is migrated but is a %T, which renders no footer", vt, a.views[vt])
851				}
852				if msg := footerGlyphProblem(fr.RenderFooter(120), state); msg != "" {
853					t.Errorf("view %q: %s (A-16 criterion 5)\n%s", vt, msg, ansi.Strip(fr.RenderFooter(120)))
854				}
855			})
856		}
857	}
858	
859	// The footer logic, on fictitious data.
860	func TestActivityGuardFooterLogic(t *testing.T) {
861		seed := func(*testing.T, *App) indicator.State { return indicator.Running }
862		const v command.ViewType = "fiction"
863		mig := map[command.ViewType][]string{v: {"x"}}
864	
865		if got := footerSeedProblems(mig, nil); len(got) != 1 || !strings.Contains(got[0], `"fiction"`) {
866			t.Errorf("a migrated view without a seed: %v", got)
867		}
868		if got := footerSeedProblems(nil, map[command.ViewType]func(*testing.T, *App) indicator.State{v: seed}); len(got) != 1 {
869			t.Errorf("a seed without a migrated view: %v", got)
870		}
871		if got := footerSeedProblems(mig, map[command.ViewType]func(*testing.T, *App) indicator.State{v: seed}); len(got) != 0 {
872			t.Errorf("a seeded migrated view: %v", got)
873		}
874	
875		run := indicator.Glyph(indicator.Running, true)
876		if msg := footerGlyphProblem("  Scanning "+run+" a", indicator.Running); msg != "" {
877			t.Errorf("a footer with the glyph: %s", msg)
878		}
879		if msg := footerGlyphProblem("  1 job running", indicator.Running); msg == "" {
880			t.Error("a footer without the glyph passed")
881		}
882		if msg := footerGlyphProblem("anything", indicator.Idle); msg == "" {
883			t.Error("an idle seed passed: it has no glyph to look for")
884		}
885	}
